#include <iostream>
#include <vector>
#include <unordered_map>
#include <bitset>
using namespace std;

const unsigned long long MOD = 1000000007ULL;

struct BigMod {
    unsigned long long val;

    BigMod(long long v = 0) {
        val = v % MOD;
        if (val < 0) val += MOD;
    }

    static unsigned long long modInverse(unsigned long long a, unsigned long long m = MOD) {
        unsigned long long g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            unsigned long long q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return (int)val; }

    BigMod& operator+=(const BigMod& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    BigMod& operator-=(const BigMod& other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    BigMod& operator*=(const BigMod& other) {
        val = (val * other.val) % MOD;
        return *this;
    }

    BigMod& operator/=(const BigMod& other) {
        return *this *= BigMod(modInverse(other.val));
    }

    friend BigMod operator+(const BigMod& a, const BigMod& b) { return BigMod(a) += b; }
    friend BigMod operator-(const BigMod& a, const BigMod& b) { return BigMod(a) -= b; }
    friend BigMod operator*(const BigMod& a, const BigMod& b) { return BigMod(a) *= b; }
    friend BigMod operator/(const BigMod& a, const BigMod& b) { return BigMod(a) /= b; }

    BigMod& operator++() {
        val = (val == MOD - 1) ? 0 : val + 1;
        return *this;
    }

    BigMod& operator--() {
        val = (val == 0) ? MOD - 1 : val - 1;
        return *this;
    }

    BigMod operator++(int) { BigMod tmp = *this; ++(*this); return tmp; }
    BigMod operator--(int) { BigMod tmp = *this; --(*this); return tmp; }

    BigMod operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const BigMod& other) const { return val == other.val; }
    bool operator!=(const BigMod& other) const { return val != other.val; }

    BigMod inv() const {
        return BigMod(modInverse(val));
    }

    BigMod pow(long long p) const {
        BigMod base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<BigMod>> prob(N, vector<BigMod>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = BigMod(p) / BigMod(100);
        }

    vector<vector<int>> count_by_pop(N + 1);
    vector<int> lookup(1 << N, -1);
    for (int m = 0; m < (1 << N); ++m) {
        int c = __builtin_popcount(m);
        lookup[m] = (int)count_by_pop[c].size();
        count_by_pop[c].push_back(m);
    }

    unordered_map<unsigned long long, BigMod> current_states;
    current_states[1ULL << lookup[0]] = 1;

    for (int layer = 0; layer < N; ++layer) {
        unordered_map<unsigned long long, BigMod> next_states;
        for (int mask = 0; mask < (1 << N); ++mask) {
            BigMod prod = 1;
            for (int r = 0; r < N; ++r) {
                bool bit_set = (mask >> r) & 1;
                prod *= bit_set ? prob[layer][r] : (BigMod(1) - prob[layer][r]);
            }
            for (auto& p : current_states) {
                unsigned long long msk = p.first;
                BigMod pval = p.second;
                unsigned long long new_msk = 0;
                for (int m : count_by_pop[layer]) {
                    if ((msk >> lookup[m]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((mask >> i) & 1) && ((m >> i) & 1) == 0) {
                                new_msk |= 1ULL << lookup[m | (1 << i)];
                            }
                        }
                    }
                }
                next_states[new_msk] += pval * prod;
            }
        }
        current_states = move(next_states);
    }

    BigMod total = 0;
    int last_idx = lookup[(1 << N) - 1];
    for (auto& p : current_states) {
        if ((p.first >> last_idx) & 1) total += p.second;
    }
    cout << (int)total << "\n";
}
